 "content": "def transform(grid):
    # Color the 2x2 objects that have at least one same-row or same-column
    # companion; retain isolated 2x2s in their original color.
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    objs = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 2 for rr in (r, r + 1) for cc in (c, c + 1)):
