 "content": "def transform(grid):
    """Color alternating 2x2 blocks, working from rightmost to leftmost."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    blocks = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 2 for rr in (r, r + 1) for cc in (c, c + 1)):
                blocks.append((r, c))

    # The rightmost block is 8; colors alternate as we move left.
    blocks.sort(key=lambda p: (p[1], p[0]))
    n = len(blocks)
    for i, (r, c) in enumerate(blocks):
        if (n - 1 - i) % 2 == 0:
            for rr in (r, r + 1):
                for cc in (c, c + 1):
                    out[rr][cc] = 8
    return out


def _make_grid(h, w, origins):
    g = [[0] * w for _ in range(h)]
    for r, c in origins:
        for rr in (r, r + 1):
            for cc in (c, c + 1):
                g[rr][cc] = 2
    return g


if __name__ == '__main__':
    demos = [
        (7, 17, [(0,0),(0,11),(1,4),(2,7),(3,1),(3,13),(4,10),(5,6),(5,15)], {(0,0),(0,11),(1,4),(2,7),(5,15)}),
