        (7, 7, [(1,5),(2,0),(4,2)], {(1,5),(2,0)}),
        (7, 5, [(1,0),(4,3)], {(4,3)}),
    ]
    for h, w, origins, expected in demos:
        result = transform(_make_grid(h, w, origins))
