                blocks.append((r, c))

    columns = sorted({c for _, c in blocks}, reverse=True)
    selected_columns = {c for i, c in enumerate(columns) if i % 2 == 0}
    for r, c in blocks:
        if c in selected_columns:
            for rr in (r, r + 1):
                for cc in (c, c + 1):
                    out[rr][cc] = 8
    return out


