 "content": "def transform(grid):
    """Recolor every other occupied object column, counted from the right."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    origins = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 2 for rr in (r, r + 1) for cc in (c, c + 1)):
                origins.append((r, c))
    cols = sorted({c for r, c in origins}, reverse=True)
    selected = {c for i, c in enumerate(cols) if i % 2 == 0}
    for r, c in origins:
        if c in selected:
            for rr in (r, r + 1):
                for cc in (c, c + 1):
                    out[rr][cc] = 8
    return out


if __name__ == '__main__':
