    demos=[(17,[(0,0,1),(0,11,1),(1,4,1),(2,7,1),(3,1,0),(3,13,0),(4,10,0),(5,6,0),(5,15,1)]),(14,[(0,12,1),(1,1,0),(1,4,0),(2,9,0),(4,3,1),(4,7,1)]),(15,[(0,6,0),(1,13,1),(2,2,0),(3,8,1),(4,5,1),(4,8,1),(5,0,1),(5,11,0)]),(7,[(1,5,1),(2,0,1),(4,2,0)]),(5,[(1,0,0),(4,3,1)])]
    for w, pts in demos:
        g=[[0]*w for _ in range(7)]
        for r,c,_ in pts:
            for rr in (r,r+1):
                for cc in (c,c+1): g[rr][cc]=2
        got={(r,c) for r,c,_ in pts if transform(g)[r][c]==8}
        exp={(r,c) for r,c,y in pts if y}
        assert got==exp,(got,exp)
    print('demos verified')
