from hermes_tools import terminal
r=terminal("python3 -c "
pts=[(17,0,0,1),(17,0,11,1),(17,1,4,1),(17,2,7,1),(17,3,1,0),(17,3,13,0),(17,4,10,0),(17,5,6,0),(17,5,15,1),(14,0,12,1),(14,1,1,0),(14,1,4,0),(14,2,9,0),(14,4,3,1),(14,4,7,1),(15,0,6,0),(15,1,13,1),(15,2,2,0),(15,3,8,1),(15,4,5,1),(15,4,8,1),(15,5,0,1),(15,5,11,0),(7,1,5,1),(7,2,0,1),(7,4,2,0),(5,1,0,0),(5,4,3,1)]
# find affine modular one-residue classifier
for m in range(2,15):
 for a in range(m):
  for b in range(m):
   for d in range(m):
    for e in range(m):
     vals={(a*r+b*c+d*w+e)%m for w,r,c,y in pts}
     if len(vals)<2: continue
     for res in vals:
      if all(((a*r+b*c+d*w+e)%m==res)==bool(y) for w,r,c,y in pts):
       print('HIT',m,a,b,d,e,res);raise SystemExit
print('no modular-affine hit')
"", timeout=30)
print(r['output'])

D=[[(0,0,1),(0,11,1),(1,4,1),(2,7,1),(3,1,0),(3,13,0),(4,10,0),(5,6,0),(5,15,1)],[(0,12,1),(1,1,0),(1,4,0),(2,9,0),(4,3,1),(4,7,1)],[(0,6,0),(1,13,1),(2,2,0),(3,8,1),(4,5,1),(4,8,1),(5,0,1),(5,11,0)],[(1,5,1),(2,0,1),(4,2,0)],[(1,0,0),(4,3,1)]]
# binary affine features on row, col, and rank of unique occupied column (sorted)
from itertools import product
valid=[]
for a,b,d,k in product(range(2), repeat=4):
 ok=True
 for items in D:
  cols=sorted(set(c for r,c,y in items)); ranks={c:i for i,c in enumerate(cols)}
  for r,c,y in items:
   if ((a*r+b*c+d*ranks[c]+k)%2)!=y: ok=False;break
  if not ok:break
 if ok: valid.append((a,b,d,k))
print('valid parity formulas:',valid)
test=[(1,7),(1,13),(2,2),(4,4),(4,11),(5,0),(5,8)]
for f in valid:
 print(f, [p for p in test if (f[0]*p[0]+f[1]*p[1]+f[2]*sorted(set(c for r,c in test)).index(p[1])+f[3])%2])

from hermes_tools import terminal
r=terminal("python3 -c "
examples=[(17,[(0,0,1),(0,11,1),(1,4,1),(2,7,1),(3,1,0),(3,13,0),(4,10,0),(5,6,0),(5,15,1)]),(14,[(0,12,1),(1,1,0),(1,4,0),(2,9,0),(4,3,1),(4,7,1)]),(15,[(0,6,0),(1,13,1),(2,2,0),(3,8,1),(4,5,1),(4,8,1),(5,0,1),(5,11,0)]),(7,[(1,5,1),(2,0,1),(4,2,0)]),(5,[(1,0,0),(4,3,1)])]
for w,pts in examples:
 cols=sorted({c for r,c,y in pts},reverse=True); selected={c for i,c in enumerate(cols) if i%2==0}
 assert {(r,c) for r,c,y in pts if y}=={(r,c) for r,c,y in pts if c in selected}
print('all 5 demonstrations match alternating distinct columns from right to left')
test=[(1,7),(1,13),(2,2),(4,4),(4,11),(5,0),(5,8)]
cols=sorted({c for r,c in test},reverse=True); chosen={c for i,c in enumerate(cols) if i%2==0}
print('descending columns:',cols); print('selected:',[(r,c) for r,c in test if c in chosen])
"", timeout=30)
print(r['output'])

