from hermes_tools import terminal
cmd=r'''python3 - <<'PY'
D=[(17,[(0,0,1),(0,11,1),(1,4,1),(2,7,1),(3,1,0),(3,13,0),(4,10,0),(5,6,0),(5,15,1)]),(14,[(0,12,1),(1,1,0),(1,4,0),(2,9,0),(4,3,1),(4,7,1)]),(15,[(0,6,0),(1,13,1),(2,2,0),(3,8,1),(4,5,1),(4,8,1),(5,0,1),(5,11,0)]),(7,[(1,5,1),(2,0,1),(4,2,0)]),(5,[(1,0,0),(4,3,1)])]
T=(15,[(1,7),(1,13),(2,2),(4,4),(4,11),(5,0),(5,8)])
features={}
for mode in ['r','c','rowmajor','colmajor','sum','diff','reverse_rowmajor','reverse_colmajor']:
  for dnum,(W,P) in enumerate(D):
    pass
# collect values by feature globally
records=[]
def add(demo,idx,name,val,y): records.append((demo,idx,name,int(val)%2,y))
for di,(W,P) in enumerate(D):
  coords=[(r,c) for r,c,y in P]; n=len(coords); h=7
  sortings={
   'rank_r':sorted(coords,key=lambda p:(p[0],p[1])),
   'rank_c':sorted(coords,key=lambda p:(p[1],p[0])),
   'rank_rowmajor':sorted(coords,key=lambda p:(p[0],p[1])),
   'rank_colmajor':sorted(coords,key=lambda p:(p[1],p[0])),
   'rank_sum':sorted(coords,key=lambda p:(p[0]+p[1],p[0],p[1])),
   'rank_diff':sorted(coords,key=lambda p:(p[0]-p[1],p[0],p[1])),
  }
  ranks={name:{p:i for i,p in enumerate(order)} for name,order in sortings.items()}
  for i,(r,c,y) in enumerate(P):
    vals={'r':r,'c':c,'r_from_bottom':h-1-r,'c_from_right':W-2-c,
      'rank_r':ranks['rank_r'][(r,c)],'rank_c':ranks['rank_c'][(r,c)],'rank_rowmajor':ranks['rank_rowmajor'][(r,c)],'rank_colmajor':ranks['rank_colmajor'][(r,c)],'rank_sum':ranks['rank_sum'][(r,c)],'rank_diff':ranks['rank_diff'][(r,c)],
      'left_count':sum(c2<c for r2,c2 in coords),'right_count':sum(c2>c for r2,c2 in coords),'above_count':sum(r2<r for r2,c2 in coords),'below_count':sum(r2>r for r2,c2 in coords),
      'same_row_count':sum(r2==r for r2,c2 in coords),'same_col_count':sum(c2==c for r2,c2 in coords),
      'same_row_left':sum(r2==r and c2<c for r2,c2 in coords),'same_row_right':sum(r2==r and c2>c for r2,c2 in coords),
      'same_col_above':sum(c2==c and r2<r for r2,c2 in coords),'same_col_below':sum(c2==c and r2>r for r2,c2 in coords),
      'num_objects':n,'W':W}
    for k,v in vals.items(): add(di,i,k,v,y)
# Test each parity feature and pairwise xor, calculate accuracy. Need all unique models exact over demos
names=sorted(set(r[2] for r in records)); exact=[]
for a in names:
 for b in [None]+names:
  if b is not None and b<a: continue
  errs=0
  for d,i,nm,v,y in records:
   va=next(x[3] for x in records if x[0]==d and x[1]==i and x[2]==a)
   vb=0 if b is None else next(x[3] for x in records if x[0]==d and x[1]==i and x[2]==b)
   errs+= (va^vb)!=y
  if errs==0: exact.append((a,b))
print('exact single/XOR feature models:',exact)
# Try calculate predictions from those on test
W,tc=T
for a,b in exact:
 print('TEST',a,b)
 # only report rank-based quick formulas
 if a in ('rank_c','rank_colmajor','left_count','right_count'):
  s=sorted(tc,key=lambda p:p[1]); n=len(s)
  print([(p, ((s.index(p)^0)%2)) for p in s])
PY'''
print(terminal(cmd)['output'])

