 "content": "def transform(grid):
    """Recolor every second distinct object column, alternating by column."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    objs = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 2 for rr in (r, r + 1) for cc in (c, c + 1)):
                objs.append((r, c))
    cols = sorted({c for r, c in objs}, reverse=True)
    selected_cols = {c for i, c in enumerate(cols) if i % 2 == 0}
    for r, c in objs:
        if c in selected_cols:
            for rr in (r, r + 1):
                for cc in (c, c + 1):
                    out[rr][cc] = 8
    return out

