        (15, [(0,6,0),(1,13,1),(2,2,0),(3,8,1),(4,5,1),(4,8,1),(5,0,1),(5,11,0)]),
        (7, [(1,5,1),(2,0,1),(4,2,0)]),
        (5, [(1,0,0),(4,3,1)]),
    ]
    for w, pts in demos:
        g = [[0]*w for _ in range(7)]
        for r,c,_ in pts:
            for rr in (r,r+1):
                for cc in (c,c+1): g[rr][cc] = 2
