from hermes_tools import terminal
cmd=r'''python3 - <<'PY'
# List all sets by each geometric ordering alternating that fit all 5 perfectly (if any). Discover exact ordering maybe row-major snake etc.
D=[[(0,0,1),(0,11,1),(1,4,1),(2,7,1),(3,1,0),(3,13,0),(4,10,0),(5,6,0),(5,15,1)],[(0,12,1),(1,1,0),(1,4,0),(2,9,0),(4,3,1),(4,7,1)],[(0,6,0),(1,13,1),(2,2,0),(3,8,1),(4,5,1),(4,8,1),(5,0,1),(5,11,0)],[(1,5,1),(2,0,1),(4,2,0)],[(1,0,0),(4,3,1)]]
orders={}
for typ in ['row','rowrev','snake','col','colrev','colsnake','diag','anti','diagrev','antirev']:
 good=0; score=0; test=[(1,7),(1,13),(2,2),(4,4),(4,11),(5,0),(5,8)]
 for P in D:
  def k(p):
   r,c,y=p
   if typ=='row':return(r,c)
   if typ=='rowrev':return(r,-c)
   if typ=='snake':return(r,c if r%2==0 else -c)
   if typ=='col':return(c,r)
   if typ=='colrev':return(c,-r)
   if typ=='colsnake':return(c,r if c%2==0 else -r)
   if typ=='diag':return(r+c,r,c)
   if typ=='anti':return(r-c,r,c)
   if typ=='diagrev':return(-r-c,r,c)
   if typ=='antirev':return(c-r,r,c)
  s=sorted(P,key=k)
  for phase in (0,1):
   if all(y==(i%2==phase) for i,(_,_,y) in enumerate(s)):
    score+=1;break
 print(typ,score)
PY'''
print(terminal(cmd,workdir='/home/USER/continual-arc-baselines/.workbench/stage1/HPL0-hermes-luna6-high-seq0/frozen/held-out/play/users/u032/system/state/workspace')['output'])

